% attested_utterance(Family, Signature, Quote, source(BibtexKey)) -- a
% quoted student utterance the corpus records for a machine this repository
% runs. Sentences, not phrases: recorded so the student register has a
% source at all, and left out of the recognition surfaces because the
% recognizer matches phrases. Mining these into phrases is authoring work
% with a citation behind it, which is the point of keeping them.
attested_utterance(addition, append_column_sum_without_carrying,
                   "A student concludes that the answer to 99 + 1 is 910 because of the failure to 'carry' the 1.",
                   source('ZDM_Ginsburg_2016_Research-inspired')).
attested_utterance(addition, count_all_instead_of_known_fact,
